    "\1\0\1\1\5\0\1\1\3\0\2\1\1\0\1\1"+
    "\4\0\1\1\3\0\3\1\5\0\1\1\6\0\1\1"+
    "\1\0\2\1\3\0\1\1\2\0\2\1\1\0\1\1"+
    "\1\0\1\1\5\0\1\1\2\0\1\1\6\0\1\1"+
    "\10\0\1\1\1\0\1\1\5\0\1\1\1\0\1\1"+
    "\2\0\2\1\1\0\3\1\2\0\1\1\1\0\1\1"+
    "\1\0\2\1\12\0\1\1\3\0\1\1\6\0\1\1"+
    "\1\0\2\1\1\0\1\1\2\0\1\1\11\0\2\1"+
    "\1\0\2\1\12\0\6\1\2\0\1\1\4\0\2\1"+
    "\2\0\1\11\2\1\2\0\1\1\2\0\2\1\1\0"+
    "\2\1";

  private static int [] zzUnpackAttribute() {
    int [] result = new int[302];
    int offset = 0;
    offset = zzUnpackAttribute(ZZ_ATTRIBUTE_PACKED_0, offset, result);
    return result;
  }

  private static int zzUnpackAttribute(String packed, int offset, int [] result) {
    int i = 0;       /* index in packed string  */
    int j = offset;  /* index in unpacked array */
    int l = packed.length();
    while (i < l) {
      int count = packed.charAt(i++);
      int value = packed.charAt(i++);
      do result[j++] = value; while (--count > 0);
    }
    return j;
  }

